installer-gui-script.script:
function rd3_check() {
    var v = system.version.ProductVersion;
    if (system.compareVersions(v, '@MACOS_MIN@') < 0 || system.compareVersions(v, '@MACOS_BEFORE@') >= 0) {
        my.result.type = 'Fatal';
        my.result.title = 'Unsupported macOS';
        my.result.message = 'This build of the RDNA3 kexts is for macOS @MACOS_MIN@ up to (not including) @MACOS_BEFORE@; this Mac runs ' + v + '.';
        return false;
    }
    return true;
}
